import { useState, useEffect } from 'react';
import API from '../../api/axios';
import toast from 'react-hot-toast';
import { useNavigate } from 'react-router-dom';

export default function UserDashboard() {
  const [userData, setUserData] = useState(null);
  const [cardData, setCardData] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [topupAmount, setTopupAmount] = useState('');
  const [selectedReceipt, setSelectedReceipt] = useState(null);
  const navigate = useNavigate();

  const userInfo = JSON.parse(localStorage.getItem('userInfo'));

  useEffect(() => {
    if (!userInfo) {
      navigate('/user/login');
      return;
    }
    fetchDashboardData();
  }, [navigate]);

  const fetchDashboardData = async () => {
    try {
      const userRes = await API.get(`/users/${userInfo._id}`);
      setUserData(userRes.data);

      const cardRes = await API.get(`/cards/user/${userInfo._id}`);
      setCardData(cardRes.data);

      const txRes = await API.get(`/transactions/user/${userInfo._id}`);
      setTransactions(txRes.data);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const handleSelfTopUp = async (e) => {
    e.preventDefault();
    if (!cardData) {
      toast.error('No card linked to top up!');
      return;
    }

    try {
      const { data } = await API.post('/transactions/topup', {
        cardUID: cardData.rfidUid,
        companyId: userInfo.companyId,
        pointsToAdd: Number(topupAmount)
      });
      toast.success(data.message);
      setTopupAmount('');
      fetchDashboardData();
    } catch (error) {
      toast.error(error.response?.data?.message || 'Top-up failed');
    }
  };

  const handleLogout = async () => {
    try {
      await API.post('/users/logout');
      localStorage.removeItem('userInfo');
      toast.success('Logged out successfully');
      navigate('/user/login');
    } catch (error) {
      toast.error('Logout failed');
    }
  };

  if (loading) return <div className="min-h-screen flex items-center justify-center text-gray-500 font-medium">Loading dashboard...</div>;

  return (
    <div className="w-full max-w-5xl mx-auto p-6 space-y-6">
      <div className="bg-gradient-to-r from-slate-900 to-indigo-950 rounded-2xl p-6 text-white shadow-xl flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <span className="text-xs uppercase tracking-widest text-indigo-400 font-semibold">Customer Portal</span>
          <h1 className="text-2xl font-bold mt-1">{userData?.fullName}</h1>
          <p className="text-xs text-slate-400 mt-0.5">{userData?.email}</p>
        </div>

        <div className="flex items-center gap-6 bg-white/10 px-6 py-4 rounded-xl backdrop-blur-md border border-white/10">
          <div>
            <p className="text-xs text-indigo-300 font-medium">Card Balance</p>
            <p className="text-3xl font-extrabold">{cardData?.pointBalance || 0} <span className="text-sm font-normal text-slate-300">Pts</span></p>
            <p className="text-[10px] text-slate-400 mt-0.5">UID: {cardData?.rfidUid || 'Unlinked'}</p>
          </div>
          <button 
            onClick={handleLogout}
            className="px-3 py-2 bg-red-500/20 hover:bg-red-500/30 text-red-300 rounded-lg text-xs font-semibold transition-colors border border-red-500/30"
          >
            Logout
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="bg-white rounded-2xl p-6 shadow-sm border border-gray-100 h-fit space-y-4">
          <h2 className="text-lg font-bold text-gray-900">Top-Up Card</h2>
          <p className="text-xs text-gray-500">Fund your physical loyalty card instantly.</p>
          
          <form onSubmit={handleSelfTopUp} className="space-y-3">
            <div>
              <label className="block text-xs font-semibold uppercase tracking-wider text-gray-600 mb-1">Points to Add</label>
              <input
                type="number"
                value={topupAmount}
                onChange={(e) => setTopupAmount(e.target.value)}
                required
                placeholder="e.g. 100"
                className="w-full px-4 py-2.5 bg-gray-50 border border-gray-200 rounded-lg text-gray-800 focus:outline-none focus:ring-2 focus:ring-indigo-500 text-sm"
              />
            </div>
            <button
              type="submit"
              className="w-full py-2.5 px-4 bg-indigo-600 hover:bg-indigo-700 text-white font-medium rounded-lg transition text-sm shadow-sm"
            >
              Fund Card
            </button>
          </form>
        </div>

        <div className="lg:col-span-2 bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
          <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center">
            <h2 className="text-lg font-bold text-gray-900">Transaction History</h2>
            <span className="text-xs text-gray-400 font-medium">{transactions.length} records</span>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-gray-50 text-[11px] font-bold uppercase tracking-wider text-gray-500">
                  <th className="px-6 py-3">Type</th>
                  <th className="px-6 py-3">Points</th>
                  <th className="px-6 py-3">Balance After</th>
                  <th className="px-6 py-3">Amount (₦)</th>
                  <th className="px-6 py-3">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 text-sm text-gray-700">
                {transactions.length === 0 ? (
                  <tr>
                    <td colSpan="5" className="px-6 py-8 text-center text-gray-400 text-sm">No activity recorded yet.</td>
                  </tr>
                ) : (
                  transactions.map((tx) => (
                    <tr key={tx._id} className="hover:bg-gray-50/80 transition-colors">
                      <td className="px-6 py-4 font-medium capitalize">
                        <span className={`px-2.5 py-1 rounded-full text-xs font-bold ${tx.type === 'topup' ? 'bg-emerald-100 text-emerald-800' : 'bg-orange-100 text-orange-800'}`}>
                          {tx.type}
                        </span>
                      </td>
                      <td className={`px-6 py-4 font-bold ${tx.type === 'topup' ? 'text-emerald-600' : 'text-orange-600'}`}>
                        {tx.type === 'topup' ? `+${tx.pointsInvolved}` : `-${tx.pointsInvolved}`}
                      </td>
                      <td className="px-6 py-4 font-semibold text-gray-800">{tx.balanceAfter} pts</td>
                      <td className="px-6 py-4 text-gray-600 font-medium">₦{tx.fiatValueNaira}</td>
                      <td className="px-6 py-4">
                        <button 
                          onClick={() => setSelectedReceipt(tx)}
                          className="text-xs text-indigo-600 font-semibold hover:underline bg-indigo-50 px-2.5 py-1.5 rounded-md"
                        >
                          Receipt
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {selectedReceipt && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-2xl max-w-sm w-full p-6 space-y-4 shadow-2xl border border-gray-100">
            <div className="text-center pb-3 border-b border-gray-100">
              <h3 className="text-lg font-bold text-gray-900">Transaction Receipt</h3>
              <p className="text-xs text-gray-400">{new Date(selectedReceipt.timestamp).toLocaleString()}</p>
            </div>
            
            <div className="space-y-2 text-sm text-gray-600">
              <div className="flex justify-between"><span>Type:</span> <span className="font-semibold uppercase text-gray-900">{selectedReceipt.type}</span></div>
              <div className="flex justify-between"><span>Points Involved:</span> <span className="font-semibold text-gray-900">{selectedReceipt.pointsInvolved} pts</span></div>
              <div className="flex justify-between"><span>Fiat Value:</span> <span className="font-semibold text-gray-900">₦{selectedReceipt.fiatValueNaira}</span></div>
              <div className="flex justify-between"><span>Ending Balance:</span> <span className="font-semibold text-gray-900">{selectedReceipt.balanceAfter} pts</span></div>
              <div className="flex justify-between"><span>Status:</span> <span className="font-semibold text-emerald-600 uppercase">{selectedReceipt.status}</span></div>
            </div>

            <button
              onClick={() => setSelectedReceipt(null)}
              className="w-full py-2.5 bg-gray-900 text-white rounded-xl text-sm font-semibold hover:bg-gray-800 transition"
            >
              Close Receipt
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
